"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["17958"],{18012(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_distribuicao_vagas.retirada_federal_deve_ser_de_ampla_concorrencia","status":422,"titulo":"No ramo federal, toda modalidade de retirada s\xf3 pode retirar da ampla concorr\xeancia"},"descricao":{"codigo":"uniplus.selecao.configuracao_distribuicao_vagas.retirada_federal_deve_ser_de_ampla_concorrencia","requisitos":[],"oQueAconteceu":["Numa distribui\xe7\xe3o de vagas com `regraDistribuicaoCodigo` do tipo Lei 12.711,\\numa modalidade selecionada com `composicaoVagas: RETIRADA_DE_OUTRA_MODALIDADE` tem\\n`composicaoOrigemCodigo` diferente de `AC` (ampla concorr\xeancia). Como nas\\ndemais causas de coer\xeancia de modalidade desta s\xe9rie,\\n`composicaoOrigemCodigo` **n\xe3o vem do corpo do pedido da defini\xe7\xe3o de distribui\xe7\xe3o\\nde vagas** \u2014 \xe9 copiado do cadastro de modalidades de Configura\xe7\xe3o, no\\nmomento em que a modalidade \xe9 selecionada (`IModalidadeReader`).","A f\xf3rmula do art. 10 \xe9 `AC = VO \u2212 VR_final \u2212 \u03A3(retiradas)` \u2014 toda retirada,\\nno ramo federal, \xe9 sempre descontada de `AC` no c\xe1lculo, **independente**\\nde qual c\xf3digo de origem a modalidade declara. O campo\\n`composicaoOrigemCodigo` existe para servir tamb\xe9m o ramo institucional e o\\nmecanismo de remanejamento (onde uma retirada pode legitimamente vir de\\noutra modalidade qualquer) \u2014 mas, no ramo federal, uma retirada com origem\\ndiferente de `AC` descontaria de `AC` sem nunca reduzir de fato a\\nmodalidade que ela alega retirar: a conta e a declara\xe7\xe3o ficariam\\ndessincronizadas.","N\xe3o acumula com nenhuma outra viola\xe7\xe3o \u2014 \xe9 a primeira que falhar que\\ninterrompe a cria\xe7\xe3o da configura\xe7\xe3o."],"comoResolver":["O campo n\xe3o est\xe1 no corpo do pedido que voc\xea enviou \u2014 est\xe1 na modalidade cadastrada\\nem Configura\xe7\xe3o. Para uma modalidade de retirada usada numa oferta da Lei\\n12.711, corrija l\xe1 o c\xf3digo de origem da modalidade para `AC`, ou remova a\\nmodalidade da sele\xe7\xe3o desta oferta se a inten\xe7\xe3o era retirar de uma\\nsub-reserva espec\xedfica \u2014 isso n\xe3o \xe9 suportado pela f\xf3rmula do art. 10 no\\nramo federal."],"ondeAparece":["Defini\xe7\xe3o de distribui\xe7\xe3o de vagas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao distribuicao vagas"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"38e6e984f8a69f1cdfcd140295a410206c687849"}}')}}]);